#include <iostream>
#include <vector>
// 종류별 이전 표만 읽어 현재 동전의 사용 한도를 보존합니다.
long long Count(int amount, const std::vector<int>& value, const std::vector<int>& limit) {
    std::vector<long long> old(static_cast<std::size_t>(amount+1),0);
    old[0]=1; // 아무 동전도 쓰지 않는 한 가지
    for(std::size_t i=0;i<value.size();++i) {
        std::vector<long long> next(static_cast<std::size_t>(amount+1),0);
        for(int a=0;a<=amount;++a)
            for(int t=0;t<=limit[i]&&t*value[i]<=a;++t)
                next[a]+=old[a-t*value[i]];
        old.swap(next);
    }
    return old[amount];
}
int main() {
    int amount,k;
    if(!(std::cin>>amount>>k)||amount<0||amount>50||k<0||k>8) return 1;
    std::vector<int> v(static_cast<std::size_t>(k)),l(static_cast<std::size_t>(k));
    bool used[51]={false};
    for(int i=0;i<k;++i) {
        if(!(std::cin>>v[i]>>l[i])||v[i]<1||v[i]>50||l[i]<0||l[i]>10||used[v[i]]) return 1;
        used[v[i]]=true;
    }
    // 모든 개수 벡터는 최대11^8개라 long long 범위 안입니다.
    std::cout<<Count(amount,v,l)<<'\n';
}
